import { FONT_WIDTHS } from './font-widths'

/**
 * Text fitting for the graphics. Satori cannot measure text, so a width is estimated from per-glyph advances measured with satori
 * itself for every bundled face (`font-widths.ts`, generated by `scripts/gen-font-widths.tsx`, validated against real renders in
 * `tests/social-font-widths.test.ts`). The estimate leans high (SAFETY), so a fitted line never overflows its box.
 */
export type FaceKey = keyof typeof FONT_WIDTHS | (string & {})
/** The face used when a layout is estimated without knowing the club's display font. */
export const DEFAULT_FACE: FaceKey = 'barlow-condensed'
export const BODY_FACE: FaceKey = 'inter-700'
export const BODY_REGULAR: FaceKey = 'inter-400'
/** The crude fallback (average glyph as a share of the size) for a face with no table. */
export const GLYPH = 0.58
const SAFETY = 1.01
/** A glyph outside the table (accents, symbols) is assumed wide. */
const UNKNOWN = 0.62

/** Estimated width in px of `text` at `px`, with extra `tracking` px between glyphs. */
export function textWidth(text: string, px: number, face: FaceKey = BODY_FACE, tracking = 0): number {
  const table = FONT_WIDTHS[face]
  let em = 0
  for (const ch of text) {
    const code = ch.codePointAt(0) ?? 0
    em += table ? (code >= 32 && code <= 126 ? table[code - 32] : UNKNOWN) : GLYPH
  }
  return Math.ceil(em * px * SAFETY + tracking * [...text].length)
}

export type FitResult = { size: number; lines: string[]; /** True only when the text had to be cut (the last resort, at the minimum size). */ truncated: boolean }

type Token = { text: string; /** What joins this token to the one before it: a space between words, nothing after a hyphen. */ sep: ' ' | '' }

/** Words, with a long hyphenated name also breakable after its hyphens ("Smith-" / "Jones"). */
function tokens(clean: string): Token[] {
  const out: Token[] = []
  for (const word of clean.split(' ').filter(Boolean)) {
    const parts = word.match(/[^-]+-?|-+/g) ?? [word]
    parts.forEach((part, i) => out.push({ text: part, sep: i === 0 ? ' ' : '' }))
  }
  return out
}
const joinTokens = (ts: readonly Token[]): string => ts.reduce((acc, t, i) => (i === 0 ? t.text : acc + t.sep + t.text), '')

/** Greedy wrap by estimated width; null when a single token is wider than the box or there are more lines than allowed. */
function wrap(ts: readonly Token[], px: number, box: number, face: FaceKey, tracking: number, max: number): string[] | null {
  const out: string[] = []
  let line: Token[] = []
  for (const t of ts) {
    const next = [...line, t]
    if (textWidth(joinTokens(next), px, face, tracking) <= box) { line = next; continue }
    if (line.length === 0 || textWidth(t.text, px, face, tracking) > box) return null
    out.push(joinTokens(line))
    line = [{ text: t.text, sep: ' ' }]
    if (out.length >= max) return null
  }
  if (line.length) out.push(joinTokens(line))
  return out.length <= max ? out : null
}

/** Cut at a word so the result plus an ellipsis fits `lines` lines at `px`. Used only when nothing fits at the minimum size. */
function cutToFit(ts: readonly Token[], px: number, box: number, face: FaceKey, tracking: number, lines: number): string[] {
  for (let n = ts.length; n > 0; n--) {
    const got = wrap([...ts.slice(0, n - 1), { ...ts[n - 1], text: `${ts[n - 1].text.replace(/-$/, '')}…` }], px, box, face, tracking, lines)
    if (got) return got
  }
  // One word wider than the box: keep as many letters as fit.
  const w = ts[0]?.text ?? ''
  for (let n = w.length; n > 1; n--) if (textWidth(`${w.slice(0, n - 1)}…`, px, face, tracking) <= box) return [`${w.slice(0, n - 1)}…`]
  return ['…']
}

/**
 * The largest size (down to `minPx`) at which `text` fits `lines` lines of `boxWidth` px, wrapped at words. A single line is preferred
 * while it stays above three quarters of `maxPx`; below that a second line keeps the text larger. Only at `minPx`, with nothing
 * fitting, is the text cut at a word with an ellipsis (`truncated`). Pure, so it is tested without a renderer.
 */
export function fitText(text: string, boxWidth: number, maxPx: number, minPx: number, lines = 2, face: FaceKey = BODY_FACE, tracking = 0): FitResult {
  const clean = text.replace(/\s+/g, ' ').trim()
  const words = tokens(clean)
  const lo = Math.min(minPx, maxPx)
  if (words.length === 0) return { size: maxPx, lines: [''], truncated: false }
  const floor1 = Math.max(lo, Math.round(maxPx * 0.75))
  for (let px = maxPx; px >= floor1; px -= 1) if (textWidth(clean, px, face, tracking) <= boxWidth) return { size: px, lines: [clean], truncated: false }
  if (lines > 1) {
    for (let px = maxPx; px >= lo; px -= 1) {
      const got = wrap(words, px, boxWidth, face, tracking, lines)
      if (got) return { size: px, lines: got, truncated: false }
    }
  } else {
    for (let px = floor1 - 1; px >= lo; px -= 1) if (textWidth(clean, px, face, tracking) <= boxWidth) return { size: px, lines: [clean], truncated: false }
  }
  return { size: lo, lines: cutToFit(words, lo, boxWidth, face, tracking, lines), truncated: true }
}
